// Weekly AI Advisor — сборка единого контекста (v7, Батч 4 Гр.6: подключён лист Meds).
// Источники (по имени ноды): Get Anomalies_Log, Get Correlations_Log, Get Daily_Trends,
// Get day_sum, Get Nutrient_Targets, Get Doctor_Notes, Get User_Profile, Get Recommendations_Log,
// Get Patient_State, Get Anamnesis, Get Symptom_Log, Get Investigations, Get Meds, Get Lab*.
// Все Get-ноды с executeOnce=true. Эта нода — Run Once for All Items.

function safeAll(name) {
  try { return $(name).all().map(i => i.json); } catch (e) { return []; }
}
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function dkey(v) { return String(v == null ? '' : v).slice(0, 10); }
function avg(arr) { const a = arr.filter(x => x != null); return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
function r1(x) { return x == null ? null : Math.round(x * 10) / 10; }

const anomRows = safeAll('Get Anomalies_Log');
const corrRows = safeAll('Get Correlations_Log');
const dailyRows = safeAll('Get Daily_Trends');
const daySumRows = safeAll('Get day_sum');
const mealsRows = safeAll('Get Meals');
const targetRows = safeAll('Get Nutrient_Targets');
const notesRows = safeAll('Get Doctor_Notes');
const profileRows = safeAll('Get User_Profile');
const pstateRows = safeAll('Get Patient_State');
const anamRows = safeAll('Get Anamnesis');
const symRows = safeAll('Get Symptom_Log');
const invRows = safeAll('Get Investigations');
const medsRows = safeAll('Get Meds');
const recRows = safeAll('Get Recommendations_Log');
const labResRows = safeAll('Get Lab Results');      // phenoage/Results: Visit_ID, Marker_ID, Value, Original_Unit, Lab_Min, Lab_Max
const labMarkRows = safeAll('Get Lab Markers');     // phenoage/Markers: Marker_ID, Name, Category, ...
const phenoLogRows = safeAll('Get PhenoAge_Log');
const labVisitRows = safeAll('Get Lab Visits');   // phenoage/Visits: Visit_ID, Date, Age_at_Visit

// --- окно анализа: последняя дата в Daily_Trends ---
const dailySorted = dailyRows
  .filter(r => r['Дата'])
  .sort((a, b) => dkey(a['Дата']).localeCompare(dkey(b['Дата'])));
const lastDate = dailySorted.length ? dkey(dailySorted[dailySorted.length - 1]['Дата']) : dkey(new Date().toISOString());
const lastMs = new Date(lastDate + 'T00:00:00Z').getTime();
const daysAgo = d => new Date(lastMs - d * 86400000).toISOString().slice(0, 10);
const win7 = daysAgo(7), win30 = daysAgo(30), win60 = daysAgo(60), win90 = daysAgo(90);

// Сегодня (Владивосток). Данные не могут быть в будущем — отсекаем битые даты.
const today = new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10);
function notFuture(d) { const k = String(d || '').slice(0, 10).replace(/\./g, '-'); return k && k <= today; }

// ================= 1. АНОМАЛИИ =================
const MIN_ABS_DELTA = {
  'VO2 Max': 2, 'RHR ночной': 3, 'HRV ночная': 6, 'Оценка сна': 7,
  'Восстановление (BB)': 12, 'Стресс дневной': 6, 'Сон (чистый, мин)': 30,
  'Эффективность сна': 4, 'Калории': 350, 'Белок': 25, 'Шаги': 3500,
};
const anomExpanded = [];
for (const row of anomRows) {
  const d = dkey(row.date);
  if (!d) continue;
  let raw = [];
  try { raw = JSON.parse(row.raw_anomalies || '[]'); } catch (e) {}
  for (const a of raw) {
    const minD = MIN_ABS_DELTA[a.label] || 0;
    if (a.value != null && a.baseline_mean != null && Math.abs(a.value - a.baseline_mean) < minD) continue;
    anomExpanded.push({ date: d, ...a });
  }
}
function groupAnoms(sinceDate) {
  const rel = anomExpanded.filter(a => a.date > sinceDate && a.date <= lastDate);
  const by = {};
  for (const a of rel) {
    if (!by[a.metric]) by[a.metric] = { label: a.label, count: 0, strong: 0, dir: a.direction, last_value: null, baseline: a.baseline_mean, worsening: 0, improving: 0, days: [] };
    const g = by[a.metric];
    g.count++;
    if (a.severity === 'strong') g.strong++;
    if (a.interpretation === 'ухудшение') g.worsening++;
    if (a.interpretation === 'улучшение') g.improving++;
    g.last_value = a.value;
    g.days.push(a.date);
  }
  const list = Object.values(by).sort((x, y) => (y.strong - x.strong) || (y.count - x.count));
  list.forEach(g => { g.days = g.days.slice(-6); });
  return list;
}
const anomalies_7d = groupAnoms(win7);
const anomalies_30d = groupAnoms(win30);

// ================= 2. КОРРЕЛЯЦИИ — ДВИЖОК ОТКЛЮЧЁН (Фаза 3) =================
// Слепой перебор пар на n≈150 для одного человека = генератор шума (коллективное ревью,
// все 3 рецензента: «выкинуть»). Целевые гипотезы теперь: симптом↔еда анализ + элиминационные тесты.
const correlations = { computed: null, disabled: true, note: 'движок корреляций отключён' };

// ================= 3. WELLNESS: НЕДЕЛЯ + ДЛИННЫЕ ОКНА =================
function sliceDaily(fromExcl, toIncl) {
  return dailySorted.filter(r => dkey(r['Дата']) > fromExcl && dkey(r['Дата']) <= toIncl);
}
function wellnessAvg(rows) {
  return {
    n_days: rows.length,
    sleep_min: r1(avg(rows.map(r => num(r['Чистый_сон_мин'])))),
    sleep_score: r1(avg(rows.map(r => num(r['Оценка_сна_балл'])))),
    hrv: r1(avg(rows.map(r => num(r['ВСР_ночная'])))),
    rhr: r1(avg(rows.map(r => num(r['Пульс_ночной_средний'])))),
    body_battery_recharge: r1(avg(rows.map(r => num(r['Восстановление_BodyBattery'])))),
    stress: r1(avg(rows.map(r => num(r['Стресс_дневной_средний'])))),
    steps: Math.round(avg(rows.map(r => num(r['Шаги_за_вчера']))) || 0),
  };
}
const lastRow = dailySorted[dailySorted.length - 1] || {};
// ACWR: Garmin считает его сам (ACWR_Garmin + ACWR_Status, Этап 5). Фолбэк — острая/хроническая.
const acute = num(lastRow['Training_Acute_Load']);
const chronic = num(lastRow['Training_Chronic_Load']);
const acwrG = num(lastRow['ACWR_Garmin']);
const wellness = {
  week: wellnessAvg(sliceDaily(win7, lastDate)),
  prev_week: wellnessAvg(sliceDaily(daysAgo(14), win7)),
  last_30d: wellnessAvg(sliceDaily(win30, lastDate)),
  last_90d: wellnessAvg(sliceDaily(win90, lastDate)),
  training_status: lastRow['Training_Status'] || null,
  acwr: acwrG != null ? acwrG : ((acute != null && chronic) ? r1(acute / chronic) : null),
  acwr_status: String(lastRow['ACWR_Status'] || '').trim().toUpperCase() || null,
  vo2max: num(lastRow['VO2_Max']),
};
const weekDaily = sliceDaily(win7, lastDate);

// ================= 4. ТАЙМЛАЙН ЛЕКАРСТВ (из Daily_Trends) =================
// Нормализуем строку лекарств в отсортированный набор, ищем изменения набора по дням.
function medSet(s) {
  if (!s) return [];
  return String(s).split(/[\n,;|]+/).map(x => x.trim()).filter(Boolean)
    .map(x => x.replace(/\s+/g, ' ')).sort();
}
const medDays = dailySorted
  .filter(r => dkey(r['Дата']) > win90)
  .map(r => ({ date: dkey(r['Дата']), set: medSet(r['Лекарства_принимаемые']) }));
const medChanges = [];
let prev = null;
for (const d of medDays) {
  const cur = d.set.join(' | ');
  if (prev !== null && cur !== prev) {
    const prevArr = prev ? prev.split(' | ') : [];
    const started = d.set.filter(m => !prevArr.includes(m));
    const stopped = prevArr.filter(m => !d.set.includes(m));
    medChanges.push({ date: d.date, started, stopped });
  }
  prev = cur;
}
let lastActive = null, lastActiveDate = null;
for (const d of medDays) { if (d.set.length) { lastActive = d.set; lastActiveDate = d.date; } }
const curSet = medDays.length ? medDays[medDays.length - 1].set : [];

// ---- картотека препаратов (лист Meds) — структурный слой поверх дневника Daily_Trends ----
function d10m(v) { const s = String(v == null ? '' : v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null; }
const medsCard = medsRows
  .filter(m => m && (m.Name || m.Med_ID) && String(m.Med_ID || '').toLowerCase() !== 'demo-format')
  .map(m => ({
    name: String(m.Name || m.Med_ID).trim(),
    class: String(m.Class || '').trim() || null,
    dose: String(m.Dose || '').trim() || null,
    schedule: String(m.Schedule || '').trim() || null,
    status: String(m.Status || '').trim().toLowerCase() || 'unknown',
    started: d10m(m.Started),
    stopped: d10m(m.Stopped),
    reason: String(m.Reason || '').trim() || null,
    prescribed_by: String(m.Prescribed_By || '').trim() || null,
  }));
const medsActive = medsCard.filter(m => ['active', 'prn', 'paused'].includes(m.status));
const medsStoppedRecent = medsCard
  .filter(m => m.status === 'stopped' && m.stopped && (new Date(lastDate) - new Date(m.stopped)) / 86400000 <= 90)
  .sort((a, b) => String(b.stopped).localeCompare(String(a.stopped)));

const medications = {
  card_active: medsActive,               // из листа Meds: что принимает, зачем, доза, кто назначил
  card_stopped_recent: medsStoppedRecent, // курсы, законченные за 90 дн — искать «откат» метрики
  daily_log_current: curSet,             // из Daily_Trends «Лекарства_принимаемые» — фактический дневной приём
  changes_last_90d: medChanges.slice(-8),
  status: medsActive.length
    ? ('по картотеке Meds: ' + medsActive.map(m => m.name + (m.dose ? ' ' + m.dose : '') + (m.reason ? ' — ' + m.reason : '')).join('; ')
        + (curSet.length ? (' | в дневнике Daily_Trends: ' + curSet.join(', ')) : ' | в дневнике Daily_Trends за последние дни не отмечено'))
    : (curSet.length ? ('по дневнику: ' + curSet.join(', ') + ' (картотека Meds пуста)')
        : (lastActiveDate ? ('препаратов нет; последний активный курс был по ' + lastActiveDate + ' (' + (lastActive || []).join(', ') + ')') : 'нет данных')),
};

// ================= 5. МЕДКАРТА (Doctor_Notes) =================
// Архив может содержать сотни старых анализов. Разделяем:
// - recent_notes: клиническая картина за последние ~9 мес
// - key_history: значимые находки любой давности (МРТ, диагнозы, «не в норме», операции, аллергии)
// Рутинные «в норме» лабораторные старше года — отбрасываем (их место в phenoage/Results, Фаза B).
const recentCutoff = daysAgo(270);
const KEY_RX = /мрт|кт |узи|диагноз|не в норме|не норм|операц|госпитал|аллерг|перелом|вывих|хроническ|экструз|грыж|коксартроз|модик|modic|глауком|радикулопат|протруз/i;
const ROUTINE_NORMAL_RX = /^(\s*)(в норме|в пределах нормы|норма\b|все показатели в норме)/i;

const allNotes = notesRows
  .filter(r => r['Date'] || r['Note'])
  .map(r => ({
    date: String(r['Date'] || '').slice(0, 10).replace(/\./g, '-'),
    date_raw: String(r['Date'] || '').slice(0, 10),
    category: r['Category'] || '',
    note: String(r['Note'] || ''),
    trigger: String(r['Trigger'] || '').slice(0, 200) || null,
    plan: String(r['Plan'] || '').slice(0, 250) || null,
  }))
  .filter(n => notFuture(n.date))
  .sort((a, b) => String(b.date).localeCompare(String(a.date)));

const recent_notes = allNotes
  .filter(n => n.date >= recentCutoff)
  .slice(0, 15)
  .map(n => ({ date: n.date_raw, category: n.category, note: n.note.slice(0, 500), trigger: n.trigger, plan: n.plan }));

const key_history = allNotes
  .filter(n => n.date < recentCutoff)
  .filter(n => KEY_RX.test(n.category + ' ' + n.note))
  .filter(n => !(String(n.category).toLowerCase().includes('лаборат') && ROUTINE_NORMAL_RX.test(n.note)))
  .slice(0, 12)
  .map(n => ({ date: n.date_raw, category: n.category, note: n.note.slice(0, 260) }));

// ================= 6. ПРОФИЛЬ ПАЦИЕНТА (User_Profile) =================
const p0 = profileRows[0] || {};
const profile = {};
for (const k of Object.keys(p0)) {
  if (['row_number', 'Telegram_ID', ''].includes(k)) continue;
  const v = String(p0[k] == null ? '' : p0[k]).trim();
  if (v) profile[k] = v.length > 1200 ? v.slice(0, 1200) + '…' : v;
}

// ================= 7. ПРОШЛЫЕ РЕКОМЕНДАЦИИ =================
const pastRecs = recRows
  .filter(r => r['Date'] && String(r['Status'] || '') !== 'init')
  .sort((a, b) => String(b['Date']).localeCompare(String(a['Date'])))
  .slice(0, 4)
  .map(r => ({
    date: String(r['Date']).slice(0, 10),
    priority: r['Priority'] || null,
    based_on: r['Based_On'] || null,
    text: String(r['Recommendation_Text'] || '').slice(0, 900),
  }));

// ================= 8. ПИТАНИЕ ЗА НЕДЕЛЮ vs ЦЕЛИ =================
const daySumSorted = daySumRows.filter(r => r['Date']).sort((a, b) => dkey(a['Date']).localeCompare(dkey(b['Date'])));
const weekNut = daySumSorted.filter(r => dkey(r['Date']) > win7 && dkey(r['Date']) <= lastDate);
const macroAvg = {
  calories: Math.round(avg(weekNut.map(r => num(r['Calories']))) || 0),
  protein_g: r1(avg(weekNut.map(r => num(r['Proteins'])))),
  carbs_g: r1(avg(weekNut.map(r => num(r['Carbs'])))),
  fats_g: r1(avg(weekNut.map(r => num(r['Fats'])))),
};
const deficits = [], excesses = [];
for (const t of targetRows) {
  const col = t['Колонка_в_Meals'];
  if (!col) continue;
  const rda = num(t['Норма_RDA_AI']);
  const ul = num(t['Верхний_предел_UL']);
  const cats = String(t['Категория'] || '').split(';').map(s => s.trim());
  const isLimit = cats.includes('Риск избытка');
  const wk = avg(weekNut.map(r => num(r[col])));
  if (wk == null) continue;
  if (isLimit && ul) {
    const pct = Math.round((wk / ul) * 100);
    if (pct > 100) excesses.push({ nutrient: t['Нутриент'], avg_per_day: r1(wk), limit: ul, unit: t['Единица'], pct_of_limit: pct });
  } else if (rda) {
    const pct = Math.round((wk / rda) * 100);
    if (pct < 85) deficits.push({ nutrient: t['Нутриент'], avg_per_day: r1(wk), target: rda, unit: t['Единица'], pct_of_target: pct, category: cats.join(', ') });
  }
}
deficits.sort((a, b) => a.pct_of_target - b.pct_of_target);
excesses.sort((a, b) => b.pct_of_limit - a.pct_of_limit);

// ================= 8a. МЕНЮ ЗА НЕДЕЛЮ (реальные блюда, не только агрегаты) =================
const mealsSorted = mealsRows.filter(r => r['Date']).sort((a, b) => dkey(a['Date']).localeCompare(dkey(b['Date'])));
const weekMealsRows = mealsSorted.filter(r => dkey(r['Date']) > win7 && dkey(r['Date']) <= lastDate);
const mealsByDay = {};
for (const m of weekMealsRows) {
  const day = dkey(m['Date']);
  (mealsByDay[day] = mealsByDay[day] || []).push({
    time: String(m['Date']).slice(11, 16),
    dish: String(m['Meal_description'] || '').trim().slice(0, 200),
    kcal: Math.round(num(m['Calories']) || 0),
    nova: m['NOVA'] || null,
  });
}
const recent_meals = Object.keys(mealsByDay).sort().map(day => ({ date: day, meals: mealsByDay[day] }));


// ================= 8b. ЛАБОРАТОРИЯ =================
const markById = {};
labMarkRows.forEach(m => { markById[m.Marker_ID] = { name: m.Name || '', unit: m.Standard_Unit || '', cat: m.Category || '' }; });
function pdRaw(s){
  s=String(s||'').trim();
  let m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/); if(m) return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');
  m=s.match(/^(\d{4})-(\d{2})-(\d{2})/); if(m) return m[0];
  return '';
}
const visitDate = {};
labVisitRows.forEach(v => { if (v.Visit_ID) visitDate[v.Visit_ID] = pdRaw(v.Date); });
function pd(vid){ return visitDate[vid] || pdRaw(vid); }  // Visit_ID -> дата через Visits, иначе парсим сам id
// последнее значение каждого маркера + флаг вне нормы
const labLatest = {};
labResRows.forEach(r => {
  const mid = r.Marker_ID; if (!mid) return;
  const val = num(r.Value); if (val == null) return;
  const dt = pd(r.Visit_ID);
  if (!labLatest[mid] || dt > labLatest[mid].date) {
    labLatest[mid] = { value: val, date: dt, lab_min: num(r.Lab_Min), lab_max: num(r.Lab_Max) };
  }
});
const labs_out_of_range = [];
const labs_recent = [];
const yearAgo = daysAgo(365);
for (const [mid, x] of Object.entries(labLatest)) {
  const nm = (markById[mid] || {}).name || mid;
  const flag = (x.lab_min != null && x.value < x.lab_min) ? 'ниже нормы'
             : (x.lab_max != null && x.value > x.lab_max) ? 'выше нормы' : null;
  const rec = { marker: nm, value: x.value, unit: (markById[mid] || {}).unit, ref: (x.lab_min ?? '') + '–' + (x.lab_max ?? ''), date: x.date, flag };
  if (flag) labs_out_of_range.push(rec);
  if (x.date >= yearAgo) labs_recent.push(rec);
}
labs_out_of_range.sort((a, b) => String(b.date).localeCompare(String(a.date)));
labs_recent.sort((a, b) => String(b.date).localeCompare(String(a.date)));

// история конкретного маркера — для лейкоцитов (частый вопрос) и что вне нормы сейчас
function markerHistory(nameRx) {
  const rows = labResRows
    .filter(r => nameRx.test((markById[r.Marker_ID] || {}).name || ''))
    .map(r => ({ date: pd(r.Visit_ID), value: num(r.Value) }))
    .filter(r => r.date && r.value != null)
    .sort((a, b) => a.date.localeCompare(b.date));
  return rows.slice(-8);
}
const lab_trends = {
  wbc: markerHistory(/лейкоциты|wbc/i),
  glucose: markerHistory(/глюкоза/i),
};

let phenoage_latest = null;
if (phenoLogRows.length) {
  const valid = phenoLogRows.filter(r => r.formula_version && r.formula_version !== 'init' && num(r.phenoage) != null);
  valid.sort((a, b) => String(b.date).localeCompare(String(a.date)));
  if (valid[0]) phenoage_latest = {
    date: pdRaw(valid[0].date) || String(valid[0].date || '').slice(0, 10), phenoage: num(valid[0].phenoage), chrono_age: num(valid[0].chrono_age),
    delta: num(valid[0].delta), markers_used: valid[0].markers_used,
  };
}

// ---- активные противопоказания (Этап 1) ----
// Opus 5: различаем «прочитал, ограничений нет» и «не смог прочитать».
// Patient_State сидирован строкой про грыжу → 0 строк = чтение не прошло (rate-limit).
// Профиль — запасной источник; поле «ОДА и неврология» с упоминанием грыжи.
const HERNIA_RX_BC = /грыж|радикулопат|протру[зи]|экструз|модик|modic|корешк/i;
const profOda = String(p0['ОДА и неврология'] || p0['ОДА и неврология '] || '');
// A6 fail-safe (ревью Opus 5, 2026-09-09): Patient_State ЗАСИЖЕН строкой про грыжу →
// 0 строк там = сбой чтения, независимо от того, прочитался ли профиль.
const pstateEmpty = pstateRows.length === 0;
const active_restrictions = pstateRows
  .filter(x => String(x.Status || '').toLowerCase() === 'active')
  .map(x => ({
    condition: x.Condition,
    stage: x.Stage || null,
    confirmed: x.Confirmed_Date || null,
    source: x.Source || null,
    contra_load: x.Contra_Load || null,
    contra_food: x.Contra_Food || null,
    contra_other: x.Contra_Other || null,
    allowed: x.Allowed || null,
    provokers: x.Provokers || null,
    review_due: x.Review_Due || null,
  }));

// В профиле упоминание грыжи без явного снятия → синтетическое ограничение.
// Срабатывает ДАЖЕ когда Patient_State пуст (профиль — подтверждение, не единственный источник).
if (!active_restrictions.length && HERNIA_RX_BC.test(profOda) &&
    !/ремисси|снят|полн(ое|ая) восстановлен|разрешена нагрузка/i.test(profOda)) {
  active_restrictions.push({
    condition: pstateEmpty
      ? 'Грыжа/радикулопатия (Patient_State не прочитан, профиль подтверждает)'
      : 'Грыжа/радикулопатия (из профиля, Patient_State без активных ограничений)',
    contra_load: 'осевая нагрузка, подъём тяжестей, скручивания, бег, прыжки, интервалы',
    allowed: /плаван|бассейн/i.test(profOda) ? 'ходьба, плавание' : 'ходьба',
    source: 'User_Profile',
    degraded: pstateEmpty || undefined,
  });
}

// restrictions_unknown ТОЛЬКО когда Patient_State не прочитан И профиль тоже не подтвердил ограничение.
const restrictions_unknown = pstateEmpty && !active_restrictions.length;

// ---- одноразовый анамнез (Этап 7): наследственность, перенесённые болезни, аллергии, образ жизни ----
const anamAnswered = anamRows.filter(a => a.Q_ID && String(a.Status) === 'answered' && String(a.Answer || '').trim());
const anamByCat = {};
for (const a of anamAnswered) {
  const cat = String(a.Category || 'прочее').split('/')[0];
  (anamByCat[cat] = anamByCat[cat] || []).push({ q: a.Question, a: String(a.Answer).trim() });
}
const anamnesis = {
  progress: anamAnswered.length + '/' + anamRows.filter(a => a.Q_ID).length,
  by_category: anamByCat,
  still_collecting: anamRows.some(a => a.Q_ID && ['pending', 'asked'].includes(String(a.Status))),
};

// ---- лист симптомов (Фаза 2): субъективные жалобы, записанные врачом-агентом структурно ----
const symValid = symRows
  .filter(s => s.Symptom && String(s.Symptom_ID || '').toLowerCase() !== 'demo-format')
  .map(s => ({
    id: s.Symptom_ID || null, date: dkey(s.Date), symptom: s.Symptom, system: s.System || '',
    severity: num(s.Severity), status: String(s.Status || '').toLowerCase(),
    change: s.Change || '', domain: s.Domain || '', context: s.Context || '',
    hypothesis: s.Hypothesis || '', note: s.Notes || '',
  }))
  .sort((a, b) => String(b.date).localeCompare(String(a.date)));
const symptoms = {
  active: symValid.filter(s => s.status === 'active' || s.status === 'monitoring').slice(0, 15),
  recently_changed: symValid.filter(s => /усил|ослаб|появ|верн|прош/i.test(s.change)).slice(0, 10),
  resolved_last_90d: symValid.filter(s => s.status === 'resolved' && s.date >= dkey(daysAgo(90))).map(s => ({ symptom: s.symptom, date: s.date })),
  total: symValid.length,
};

// ---- расследования (Фаза 4): активные разборы врача-агента ----
const investigations = invRows
  .filter(v => v.Inv_ID && String(v.Inv_ID).toLowerCase() !== 'demo-format' && String(v.Status || '').toLowerCase() !== 'closed')
  .map(v => ({
    id: v.Inv_ID, opened: dkey(v.Opened), status: String(v.Status || '').toLowerCase(),
    trigger: v.Trigger || '', detail: v.Trigger_Detail || '', hypothesis: v.Hypothesis || '',
    pending: v.Questions_Pending || '', labs: v.Labs_Suggested || '', referral: v.Referral || '',
    brief: v.Doctor_Brief || '',
  }))
  .sort((a, b) => String(b.opened).localeCompare(String(a.opened)));

// ================= КОНТЕКСТ =================
const context = {
  today,
  data_coverage: 'wellness по ' + lastDate + ', nutrition по ' + (daySumSorted.length ? dkey(daySumSorted[daySumSorted.length-1]['Date']) : '?'),
  patient_profile: profile,
  anamnesis,             // одноразовый сбор: наследственность / перенесённые болезни / операции / аллергии / образ жизни
  symptoms,              // субъективные жалобы (лист Symptom_Log). Сопоставляй динамику с питанием/активностью/лекарствами.
  investigations,        // активные расследования врача-агента (лист Investigations). Учитывай, не дублируй.
  active_restrictions,   // ЖЁСТКИЕ ограничения. Нельзя советовать ничего из contra_*. Разрешено только из allowed.
  restrictions_unknown,  // true = Patient_State не прочитан И профиль не подтвердил ограничение → «ограничения действуют, режем всё»
  medical_record_recent: recent_notes,
  medical_history_key: key_history,
  medications,
  past_recommendations: pastRecs,
  window: { from: win7, to: lastDate, days_with_wellness: weekDaily.length, days_with_nutrition: weekNut.length },
  anomalies_last_7d: anomalies_7d,
  anomalies_last_30d: anomalies_30d,
  correlations,
  wellness,
  nutrition: { macros_avg_per_day: macroAvg, deficits, excesses, recent_meals },
  labs: { phenoage: phenoage_latest, out_of_range: labs_out_of_range, recent: labs_recent.slice(0, 20), trends: lab_trends },
};

return [{ json: { context } }];

// Разбор ответа LLM + строка для Recommendations_Log (v4, Батч 4 Группа 3).
// Отличия от v3:
//  - ЭСКАЛАЦИЯ: если этот разбор без действий И прошлый разбор тоже был без действий —
//    2 недели подряд замкнутый цикл сломан → 🔴 в Telegram сверху, Status='без_действий_эскалация',
//    Priority='высокий'. Читает Get Recommendations_Log.
//  v3: машинный блок обязателен, не падаем при его отсутствии; фильтр Patient_State по regex+type;
//  slice(0,3) после фильтра.
const inp = $input.first().json;
let text = String(inp.text || inp.output || inp.response || '').trim();

const ctx = (() => {
  try { return $('Build Context').first().json.context; } catch (e) { return {}; }
})();

if (!text) throw new Error('LLM вернул пустой ответ');

// ---------- вырезаем машинный блок ----------
const ACTIONS_RX = /<<<ACTIONS\s*([\s\S]*?)\s*ACTIONS>>>/;
const m = text.match(ACTIONS_RX);
let blockMissing = !m;
let parsed = [];
if (m) {
  text = text.replace(ACTIONS_RX, '').trim();   // проза без блока — уйдёт в Telegram
  try {
    const j = JSON.parse(m[1].trim());
    parsed = Array.isArray(j) ? j : (Array.isArray(j && j.actions) ? j.actions : []);
  } catch (e) {
    blockMissing = true;   // невалидный JSON = блока фактически нет
  }
}
if (!text) throw new Error('LLM вернул пустой текст разбора (без машинного блока)');

const ALLOWED = ['sleep_min','sleep_score','sleep_eff','hrv','rhr','body_battery','stress','steps','vo2max'];
const ACTION_TYPES = ['load_high','load_low','walk','swim','diet','supplement','sleep','stress','medical','other'];
let actions = parsed
  .filter(a => a && a.title)
  .map(a => ({
    title: String(a.title).slice(0, 120),
    why: a.why ? String(a.why).slice(0, 400) : '',
    expect: a.expect ? String(a.expect).slice(0, 300) : '',
    priority: ['высокий','средний','низкий'].includes(a.priority) ? a.priority : 'средний',
    metric: ALLOWED.includes(a.metric) ? a.metric : null,
    type: ACTION_TYPES.includes(a.type) ? a.type : 'unknown',
  }));

// Алерты собираем отдельно — уйдут ОТДЕЛЬНЫМ, заметным сообщением перед разбором.
const alerts = [];

// ---------- фильтр Patient_State (Opus 5: пол regex + type, а не вместо) ----------
const LOAD_RX = /интенсив|интервал|hiit|бег|пробеж|прыж|присед|становая|штанг|турник|подтяг|отжим|планк|скручиван|макгил|ротац|наклон|подним[а-яё]*\s+(?:тяж|вес)|подн(ять|имать)\s+(?:тяж|вес)|тяж(?:есть|ести|[её]л)|спринт|силов|кроссфит|бадминтон|берпи|выпад|растяж|мобилити|йог|лфк|упражнен|качат|тренаж|планк|берпи|подтягив|скакалк|степ[- ]аэроб|ударн/i;
const restrUnknown = !!ctx.restrictions_unknown;
const loadRestr = (ctx.active_restrictions || []).filter(r =>
  String(r.contra_load || '').trim() &&
  String(r.status || r.Status || 'active').toLowerCase() !== 'resolved');

let blocked = [];
if (restrUnknown || loadRestr.length) {
  const allowedRaw = loadRestr.map(r => String(r.allowed || '')).join(' ').toLowerCase();
  const allowWalk = !restrUnknown && /ходьб|walk|прогул/.test(allowedRaw);
  const allowSwim = !restrUnknown && /плаван|бассейн|swim/.test(allowedRaw);
  const allowedList = restrUnknown ? 'ходьба' : (loadRestr.map(r => r.allowed).filter(Boolean).join('; ') || 'ходьба, плавание');
  const kept = [];
  for (const a of actions) {
    const t = a.type;
    let drop = false;
    if (t === 'load_high' || t === 'load_low') drop = true;
    else if (t === 'walk') drop = !allowWalk;
    else if (t === 'swim') drop = !allowSwim;
    else if (LOAD_RX.test(a.title + ' ' + a.why)) drop = true;
    else if (restrUnknown && (t === 'unknown' || !t)) drop = true;
    if (drop) blocked.push(a.title); else kept.push(a);
  }
  actions = kept;
  if (restrUnknown) {
    alerts.push('⚠️ Не удалось прочитать карту пациента (Patient_State/профиль). Ограничения по спине приняты как ДЕЙСТВУЮЩИЕ — нагрузочные действия вырезаны. Проверь советник.');
  } else if (blocked.length) {
    text += '\n\n⚠️ Отфильтровано (противоречит активному ограничению по спине): '
      + blocked.join('; ') + '. Разрешено: ' + allowedList + '.';
  }
}

// slice(0,3) — ПОСЛЕ фильтра
actions = actions.slice(0, 3);
const noActions = actions.length === 0;
if (blockMissing || noActions) {
  alerts.push('⚠️ Советник не сформулировал действия на эту неделю. Разбор ниже — посмотри глазами.');
}
const okActions = actions.length > 0 && !blockMissing && !noActions;

// ---------- ЭСКАЛАЦИЯ: 2 разбора подряд без действий (Батч 4, Группа 3) ----------
const todayDate = (ctx.window && ctx.window.to) || new Date().toISOString().slice(0, 10);
let escalate = false;
if (!okActions) {
  try {
    const prev = $('Get Recommendations_Log').all().map(i => i.json)
      .filter(r => r && r.Date && String(r.Period_Type || 'weekly') === 'weekly'
        && String(r.Date).slice(0, 10) !== String(todayDate).slice(0, 10))
      .sort((a, b) => String(b.Date).localeCompare(String(a.Date)))[0];
    if (prev && /без_действий/.test(String(prev.Status || ''))) escalate = true;
  } catch (e) { /* нет ноды/данных — эскалацию не поднимаем */ }
}
if (escalate) {
  alerts.unshift('🔴 ЭСКАЛАЦИЯ: советник ВТОРУЮ неделю подряд не может сформулировать действия. Замкнутый цикл «совет → эффект» сломан — LLM не возвращает валидный машинный блок, либо контекст пустой. Нужна ручная проверка советника (Build Context / промпт / модель).');
}

// ---------- контекст «на основании чего» ----------
const based = [];
const a7 = ctx.anomalies_last_7d || [];
if (a7.length) based.push('аномалии_7д: ' + a7.map(a => a.label).join(', '));
if (ctx.correlations && ctx.correlations.priority && ctx.correlations.priority.length)
  based.push('корреляции: ' + ctx.correlations.priority.length);
if (ctx.nutrition && ctx.nutrition.deficits && ctx.nutrition.deficits.length)
  based.push('дефициты: ' + ctx.nutrition.deficits.map(d => d.nutrient).join(', '));
if (ctx.nutrition && ctx.nutrition.excesses && ctx.nutrition.excesses.length)
  based.push('избытки: ' + ctx.nutrition.excesses.map(d => d.nutrient).join(', '));
if (ctx.wellness && ctx.wellness.acwr != null) based.push('ACWR ' + ctx.wellness.acwr);
if (blocked.length) based.push('гейт: вырезано ' + blocked.length);
if (blockMissing) based.push('!!! машинный блок не пришёл');
else if (noActions) based.push('!!! действий 0');
if (escalate) based.push('!!! ЭСКАЛАЦИЯ 2х без_действий подряд');

const strong7 = a7.reduce((s, a) => s + (a.strong || 0), 0);
const priority = escalate ? 'высокий' : (strong7 >= 3 ? 'высокий' : strong7 >= 1 ? 'средний' : 'низкий');

// Машинный хвост — В КОНЕЦ сохраняемого текста (Telegram его не видит).
const tailObj = { actions, issued: (ctx.window && ctx.window.to) || null, blocked_by_gate: blocked };
if (blockMissing) tailObj.note = 'советник не вернул машинный блок';
else if (noActions) tailObj.note = 'советник вернул блок без действий';
else if (actions.length === 0) tailObj.note = 'все действия вырезаны фильтром Patient_State';
if (escalate) tailObj.escalation = true;
const tail = '\n\n<<<ACTIONS\n' + JSON.stringify(tailObj) + '\nACTIONS>>>';

if (blocked.length) {
  alerts.push('⚠️ ' + blocked.length + ' действие(й) вырезано фильтром Patient_State (противоречат ограничению по спине). Проверь, что осталось.');
}

return [{
  json: {
    Date: todayDate,
    Period_Type: 'weekly',
    Recommendation_Text: text + tail,
    Telegram_Text: (alerts.length
      ? alerts.join('\n\n') + '\n\n━━━━━━━━━━\n\n'
      : '') + text,
    Alert_Text: alerts.join('\n\n'),
    Has_Alert: alerts.length > 0,
    Based_On: based.join(' | '),
    Status: okActions ? 'отправлено' : (escalate ? 'без_действий_эскалация' : 'без_действий'),
    Priority: priority,
  }
}];

// Weekly AI Advisor — сборка единого контекста (v7, Батч 4 Гр.6: подключён лист Meds).
// Источники (по имени ноды): Get Anomalies_Log, Get Correlations_Log, Get Daily_Trends,
// Get day_sum, Get Nutrient_Targets, Get Doctor_Notes, Get User_Profile, Get Recommendations_Log,
// Get Patient_State, Get Anamnesis, Get Symptom_Log, Get Investigations, Get Meds, Get Lab*.
// Все Get-ноды с executeOnce=true. Эта нода — Run Once for All Items.

function safeAll(name) {
  try { return $(name).all().map(i => i.json); } catch (e) { return []; }
}
function num(v) {
  if (v === null || v === undefined || v === '') return null;
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v).replace('%', '').replace(',', '.'));
  return isNaN(n) ? null : n;
}
function dkey(v) { return String(v == null ? '' : v).slice(0, 10); }
function avg(arr) { const a = arr.filter(x => x != null); return a.length ? a.reduce((s, x) => s + x, 0) / a.length : null; }
function r1(x) { return x == null ? null : Math.round(x * 10) / 10; }

const anomRows = safeAll('Get Anomalies_Log');
const corrRows = safeAll('Get Correlations_Log');
const dailyRows = safeAll('Get Daily_Trends');
const daySumRows = safeAll('Get day_sum');
const mealsRows = safeAll('Get Meals');
const targetRows = safeAll('Get Nutrient_Targets');
const notesRows = safeAll('Get Doctor_Notes');
const profileRows = safeAll('Get User_Profile');
const pstateRows = safeAll('Get Patient_State');
const anamRows = safeAll('Get Anamnesis');
const symRows = safeAll('Get Symptom_Log');
const invRows = safeAll('Get Investigations');
const medsRows = safeAll('Get Meds');
const recRows = safeAll('Get Recommendations_Log');
const labResRows = safeAll('Get Lab Results');      // phenoage/Results: Visit_ID, Marker_ID, Value, Original_Unit, Lab_Min, Lab_Max
const labMarkRows = safeAll('Get Lab Markers');     // phenoage/Markers: Marker_ID, Name, Category, ...
const phenoLogRows = safeAll('Get PhenoAge_Log');
const labVisitRows = safeAll('Get Lab Visits');   // phenoage/Visits: Visit_ID, Date, Age_at_Visit

// --- окно анализа: последняя дата в Daily_Trends ---
const dailySorted = dailyRows
  .filter(r => r['Дата'])
  .sort((a, b) => dkey(a['Дата']).localeCompare(dkey(b['Дата'])));
const lastDate = dailySorted.length ? dkey(dailySorted[dailySorted.length - 1]['Дата']) : dkey(new Date().toISOString());
const lastMs = new Date(lastDate + 'T00:00:00Z').getTime();
const daysAgo = d => new Date(lastMs - d * 86400000).toISOString().slice(0, 10);
const win7 = daysAgo(7), win30 = daysAgo(30), win60 = daysAgo(60), win90 = daysAgo(90);

// Сегодня (Владивосток). Данные не могут быть в будущем — отсекаем битые даты.
const today = new Date(Date.now() + 10 * 3600 * 1000).toISOString().slice(0, 10);
function notFuture(d) { const k = String(d || '').slice(0, 10).replace(/\./g, '-'); return k && k <= today; }

// ================= 1. АНОМАЛИИ =================
const MIN_ABS_DELTA = {
  'VO2 Max': 2, 'RHR ночной': 3, 'HRV ночная': 6, 'Оценка сна': 7,
  'Восстановление (BB)': 12, 'Стресс дневной': 6, 'Сон (чистый, мин)': 30,
  'Эффективность сна': 4, 'Калории': 350, 'Белок': 25, 'Шаги': 3500,
};
const anomExpanded = [];
for (const row of anomRows) {
  const d = dkey(row.date);
  if (!d) continue;
  let raw = [];
  try { raw = JSON.parse(row.raw_anomalies || '[]'); } catch (e) {}
  for (const a of raw) {
    const minD = MIN_ABS_DELTA[a.label] || 0;
    if (a.value != null && a.baseline_mean != null && Math.abs(a.value - a.baseline_mean) < minD) continue;
    anomExpanded.push({ date: d, ...a });
  }
}
function groupAnoms(sinceDate) {
  const rel = anomExpanded.filter(a => a.date > sinceDate && a.date <= lastDate);
  const by = {};
  for (const a of rel) {
    if (!by[a.metric]) by[a.metric] = { label: a.label, count: 0, strong: 0, dir: a.direction, last_value: null, baseline: a.baseline_mean, worsening: 0, improving: 0, days: [] };
    const g = by[a.metric];
    g.count++;
    if (a.severity === 'strong') g.strong++;
    if (a.interpretation === 'ухудшение') g.worsening++;
    if (a.interpretation === 'улучшение') g.improving++;
    g.last_value = a.value;
    g.days.push(a.date);
  }
  const list = Object.values(by).sort((x, y) => (y.strong - x.strong) || (y.count - x.count));
  list.forEach(g => { g.days = g.days.slice(-6); });
  return list;
}
const anomalies_7d = groupAnoms(win7);
const anomalies_30d = groupAnoms(win30);

// ================= 2. КОРРЕЛЯЦИИ — ДВИЖОК ОТКЛЮЧЁН (Фаза 3) =================
// Слепой перебор пар на n≈150 для одного человека = генератор шума (коллективное ревью,
// все 3 рецензента: «выкинуть»). Целевые гипотезы теперь: симптом↔еда анализ + элиминационные тесты.
const correlations = { computed: null, disabled: true, note: 'движок корреляций отключён' };

// ================= 3. WELLNESS: НЕДЕЛЯ + ДЛИННЫЕ ОКНА =================
function sliceDaily(fromExcl, toIncl) {
  return dailySorted.filter(r => dkey(r['Дата']) > fromExcl && dkey(r['Дата']) <= toIncl);
}
function wellnessAvg(rows) {
  return {
    n_days: rows.length,
    sleep_min: r1(avg(rows.map(r => num(r['Чистый_сон_мин'])))),
    sleep_score: r1(avg(rows.map(r => num(r['Оценка_сна_балл'])))),
    hrv: r1(avg(rows.map(r => num(r['ВСР_ночная'])))),
    rhr: r1(avg(rows.map(r => num(r['Пульс_ночной_средний'])))),
    body_battery_recharge: r1(avg(rows.map(r => num(r['Восстановление_BodyBattery'])))),
    stress: r1(avg(rows.map(r => num(r['Стресс_дневной_средний'])))),
    steps: Math.round(avg(rows.map(r => num(r['Шаги_за_вчера']))) || 0),
  };
}
const lastRow = dailySorted[dailySorted.length - 1] || {};
// ACWR: Garmin считает его сам (ACWR_Garmin + ACWR_Status, Этап 5). Фолбэк — острая/хроническая.
const acute = num(lastRow['Training_Acute_Load']);
const chronic = num(lastRow['Training_Chronic_Load']);
const acwrG = num(lastRow['ACWR_Garmin']);
const wellness = {
  week: wellnessAvg(sliceDaily(win7, lastDate)),
  prev_week: wellnessAvg(sliceDaily(daysAgo(14), win7)),
  last_30d: wellnessAvg(sliceDaily(win30, lastDate)),
  last_90d: wellnessAvg(sliceDaily(win90, lastDate)),
  training_status: lastRow['Training_Status'] || null,
  acwr: acwrG != null ? acwrG : ((acute != null && chronic) ? r1(acute / chronic) : null),
  acwr_status: String(lastRow['ACWR_Status'] || '').trim().toUpperCase() || null,
  vo2max: num(lastRow['VO2_Max']),
};
const weekDaily = sliceDaily(win7, lastDate);

// ================= 4. ТАЙМЛАЙН ЛЕКАРСТВ (из Daily_Trends) =================
// Нормализуем строку лекарств в отсортированный набор, ищем изменения набора по дням.
function medSet(s) {
  if (!s) return [];
  return String(s).split(/[\n,;|]+/).map(x => x.trim()).filter(Boolean)
    .map(x => x.replace(/\s+/g, ' ')).sort();
}
const medDays = dailySorted
  .filter(r => dkey(r['Дата']) > win90)
  .map(r => ({ date: dkey(r['Дата']), set: medSet(r['Лекарства_принимаемые']) }));
const medChanges = [];
let prev = null;
for (const d of medDays) {
  const cur = d.set.join(' | ');
  if (prev !== null && cur !== prev) {
    const prevArr = prev ? prev.split(' | ') : [];
    const started = d.set.filter(m => !prevArr.includes(m));
    const stopped = prevArr.filter(m => !d.set.includes(m));
    medChanges.push({ date: d.date, started, stopped });
  }
  prev = cur;
}
let lastActive = null, lastActiveDate = null;
for (const d of medDays) { if (d.set.length) { lastActive = d.set; lastActiveDate = d.date; } }
const curSet = medDays.length ? medDays[medDays.length - 1].set : [];

// ---- картотека препаратов (лист Meds) — структурный слой поверх дневника Daily_Trends ----
function d10m(v) { const s = String(v == null ? '' : v).trim().slice(0, 10); return /^\d{4}-\d{2}-\d{2}$/.test(s) ? s : null; }
const medsCard = medsRows
  .filter(m => m && (m.Name || m.Med_ID) && String(m.Med_ID || '').toLowerCase() !== 'demo-format')
  .map(m => ({
    name: String(m.Name || m.Med_ID).trim(),
    class: String(m.Class || '').trim() || null,
    dose: String(m.Dose || '').trim() || null,
    schedule: String(m.Schedule || '').trim() || null,
    status: String(m.Status || '').trim().toLowerCase() || 'unknown',
    started: d10m(m.Started),
    stopped: d10m(m.Stopped),
    reason: String(m.Reason || '').trim() || null,
    prescribed_by: String(m.Prescribed_By || '').trim() || null,
  }));
const medsActive = medsCard.filter(m => ['active', 'prn', 'paused'].includes(m.status));
const medsStoppedRecent = medsCard
  .filter(m => m.status === 'stopped' && m.stopped && (new Date(lastDate) - new Date(m.stopped)) / 86400000 <= 90)
  .sort((a, b) => String(b.stopped).localeCompare(String(a.stopped)));

const medications = {
  card_active: medsActive,               // из листа Meds: что принимает, зачем, доза, кто назначил
  card_stopped_recent: medsStoppedRecent, // курсы, законченные за 90 дн — искать «откат» метрики
  daily_log_current: curSet,             // из Daily_Trends «Лекарства_принимаемые» — фактический дневной приём
  changes_last_90d: medChanges.slice(-8),
  status: medsActive.length
    ? ('по картотеке Meds: ' + medsActive.map(m => m.name + (m.dose ? ' ' + m.dose : '') + (m.reason ? ' — ' + m.reason : '')).join('; ')
        + (curSet.length ? (' | в дневнике Daily_Trends: ' + curSet.join(', ')) : ' | в дневнике Daily_Trends за последние дни не отмечено'))
    : (curSet.length ? ('по дневнику: ' + curSet.join(', ') + ' (картотека Meds пуста)')
        : (lastActiveDate ? ('препаратов нет; последний активный курс был по ' + lastActiveDate + ' (' + (lastActive || []).join(', ') + ')') : 'нет данных')),
};

// ================= 5. МЕДКАРТА (Doctor_Notes) =================
// Архив может содержать сотни старых анализов. Разделяем:
// - recent_notes: клиническая картина за последние ~9 мес
// - key_history: значимые находки любой давности (МРТ, диагнозы, «не в норме», операции, аллергии)
// Рутинные «в норме» лабораторные старше года — отбрасываем (их место в phenoage/Results, Фаза B).
const recentCutoff = daysAgo(270);
const KEY_RX = /мрт|кт |узи|диагноз|не в норме|не норм|операц|госпитал|аллерг|перелом|вывих|хроническ|экструз|грыж|коксартроз|модик|modic|глауком|радикулопат|протруз/i;
const ROUTINE_NORMAL_RX = /^(\s*)(в норме|в пределах нормы|норма\b|все показатели в норме)/i;

const allNotes = notesRows
  .filter(r => r['Date'] || r['Note'])
  .map(r => ({
    date: String(r['Date'] || '').slice(0, 10).replace(/\./g, '-'),
    date_raw: String(r['Date'] || '').slice(0, 10),
    category: r['Category'] || '',
    note: String(r['Note'] || ''),
    trigger: String(r['Trigger'] || '').slice(0, 200) || null,
    plan: String(r['Plan'] || '').slice(0, 250) || null,
  }))
  .filter(n => notFuture(n.date))
  .sort((a, b) => String(b.date).localeCompare(String(a.date)));

const recent_notes = allNotes
  .filter(n => n.date >= recentCutoff)
  .slice(0, 15)
  .map(n => ({ date: n.date_raw, category: n.category, note: n.note.slice(0, 500), trigger: n.trigger, plan: n.plan }));

const key_history = allNotes
  .filter(n => n.date < recentCutoff)
  .filter(n => KEY_RX.test(n.category + ' ' + n.note))
  .filter(n => !(String(n.category).toLowerCase().includes('лаборат') && ROUTINE_NORMAL_RX.test(n.note)))
  .slice(0, 12)
  .map(n => ({ date: n.date_raw, category: n.category, note: n.note.slice(0, 260) }));

// ================= 6. ПРОФИЛЬ ПАЦИЕНТА (User_Profile) =================
const p0 = profileRows[0] || {};
const profile = {};
for (const k of Object.keys(p0)) {
  if (['row_number', 'Telegram_ID', ''].includes(k)) continue;
  const v = String(p0[k] == null ? '' : p0[k]).trim();
  if (v) profile[k] = v.length > 1200 ? v.slice(0, 1200) + '…' : v;
}

// ================= 7. ПРОШЛЫЕ РЕКОМЕНДАЦИИ =================
const pastRecs = recRows
  .filter(r => r['Date'] && String(r['Status'] || '') !== 'init')
  .sort((a, b) => String(b['Date']).localeCompare(String(a['Date'])))
  .slice(0, 4)
  .map(r => ({
    date: String(r['Date']).slice(0, 10),
    priority: r['Priority'] || null,
    based_on: r['Based_On'] || null,
    text: String(r['Recommendation_Text'] || '').slice(0, 900),
  }));

// ================= 8. ПИТАНИЕ ЗА НЕДЕЛЮ vs ЦЕЛИ =================
const daySumSorted = daySumRows.filter(r => r['Date']).sort((a, b) => dkey(a['Date']).localeCompare(dkey(b['Date'])));
const weekNut = daySumSorted.filter(r => dkey(r['Date']) > win7 && dkey(r['Date']) <= lastDate);
const macroAvg = {
  calories: Math.round(avg(weekNut.map(r => num(r['Calories']))) || 0),
  protein_g: r1(avg(weekNut.map(r => num(r['Proteins'])))),
  carbs_g: r1(avg(weekNut.map(r => num(r['Carbs'])))),
  fats_g: r1(avg(weekNut.map(r => num(r['Fats'])))),
};
const deficits = [], excesses = [];
for (const t of targetRows) {
  const col = t['Колонка_в_Meals'];
  if (!col) continue;
  const rda = num(t['Норма_RDA_AI']);
  const ul = num(t['Верхний_предел_UL']);
  const cats = String(t['Категория'] || '').split(';').map(s => s.trim());
  const isLimit = cats.includes('Риск избытка');
  const wk = avg(weekNut.map(r => num(r[col])));
  if (wk == null) continue;
  if (isLimit && ul) {
    const pct = Math.round((wk / ul) * 100);
    if (pct > 100) excesses.push({ nutrient: t['Нутриент'], avg_per_day: r1(wk), limit: ul, unit: t['Единица'], pct_of_limit: pct });
  } else if (rda) {
    const pct = Math.round((wk / rda) * 100);
    if (pct < 85) deficits.push({ nutrient: t['Нутриент'], avg_per_day: r1(wk), target: rda, unit: t['Единица'], pct_of_target: pct, category: cats.join(', ') });
  }
}
deficits.sort((a, b) => a.pct_of_target - b.pct_of_target);
excesses.sort((a, b) => b.pct_of_limit - a.pct_of_limit);

// ================= 8a. МЕНЮ ЗА НЕДЕЛЮ (реальные блюда, не только агрегаты) =================
const mealsSorted = mealsRows.filter(r => r['Date']).sort((a, b) => dkey(a['Date']).localeCompare(dkey(b['Date'])));
const weekMealsRows = mealsSorted.filter(r => dkey(r['Date']) > win7 && dkey(r['Date']) <= lastDate);
const mealsByDay = {};
for (const m of weekMealsRows) {
  const day = dkey(m['Date']);
  (mealsByDay[day] = mealsByDay[day] || []).push({
    time: String(m['Date']).slice(11, 16),
    dish: String(m['Meal_description'] || '').trim().slice(0, 200),
    kcal: Math.round(num(m['Calories']) || 0),
    nova: m['NOVA'] || null,
  });
}
const recent_meals = Object.keys(mealsByDay).sort().map(day => ({ date: day, meals: mealsByDay[day] }));


// ================= 8b. ЛАБОРАТОРИЯ =================
const markById = {};
labMarkRows.forEach(m => { markById[m.Marker_ID] = { name: m.Name || '', unit: m.Standard_Unit || '', cat: m.Category || '' }; });
function pdRaw(s){
  s=String(s||'').trim();
  let m=s.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/); if(m) return m[3]+'-'+m[2].padStart(2,'0')+'-'+m[1].padStart(2,'0');
  m=s.match(/^(\d{4})-(\d{2})-(\d{2})/); if(m) return m[0];
  return '';
}
const visitDate = {};
labVisitRows.forEach(v => { if (v.Visit_ID) visitDate[v.Visit_ID] = pdRaw(v.Date); });
function pd(vid){ return visitDate[vid] || pdRaw(vid); }  // Visit_ID -> дата через Visits, иначе парсим сам id
// последнее значение каждого маркера + флаг вне нормы
const labLatest = {};
labResRows.forEach(r => {
  const mid = r.Marker_ID; if (!mid) return;
  const val = num(r.Value); if (val == null) return;
  const dt = pd(r.Visit_ID);
  if (!labLatest[mid] || dt > labLatest[mid].date) {
    labLatest[mid] = { value: val, date: dt, lab_min: num(r.Lab_Min), lab_max: num(r.Lab_Max) };
  }
});
const labs_out_of_range = [];
const labs_recent = [];
const yearAgo = daysAgo(365);
for (const [mid, x] of Object.entries(labLatest)) {
  const nm = (markById[mid] || {}).name || mid;
  const flag = (x.lab_min != null && x.value < x.lab_min) ? 'ниже нормы'
             : (x.lab_max != null && x.value > x.lab_max) ? 'выше нормы' : null;
  const rec = { marker: nm, value: x.value, unit: (markById[mid] || {}).unit, ref: (x.lab_min ?? '') + '–' + (x.lab_max ?? ''), date: x.date, flag };
  if (flag) labs_out_of_range.push(rec);
  if (x.date >= yearAgo) labs_recent.push(rec);
}
labs_out_of_range.sort((a, b) => String(b.date).localeCompare(String(a.date)));
labs_recent.sort((a, b) => String(b.date).localeCompare(String(a.date)));

// история конкретного маркера — для лейкоцитов (частый вопрос) и что вне нормы сейчас
function markerHistory(nameRx) {
  const rows = labResRows
    .filter(r => nameRx.test((markById[r.Marker_ID] || {}).name || ''))
    .map(r => ({ date: pd(r.Visit_ID), value: num(r.Value) }))
    .filter(r => r.date && r.value != null)
    .sort((a, b) => a.date.localeCompare(b.date));
  return rows.slice(-8);
}
const lab_trends = {
  wbc: markerHistory(/лейкоциты|wbc/i),
  glucose: markerHistory(/глюкоза/i),
};

let phenoage_latest = null;
if (phenoLogRows.length) {
  const valid = phenoLogRows.filter(r => r.formula_version && r.formula_version !== 'init' && num(r.phenoage) != null);
  valid.sort((a, b) => String(b.date).localeCompare(String(a.date)));
  if (valid[0]) phenoage_latest = {
    date: pdRaw(valid[0].date) || String(valid[0].date || '').slice(0, 10), phenoage: num(valid[0].phenoage), chrono_age: num(valid[0].chrono_age),
    delta: num(valid[0].delta), markers_used: valid[0].markers_used,
  };
}

// ---- активные противопоказания (Этап 1) ----
// Opus 5: различаем «прочитал, ограничений нет» и «не смог прочитать».
// Patient_State сидирован строкой про грыжу → 0 строк = чтение не прошло (rate-limit).
// Профиль — запасной источник; поле «ОДА и неврология» с упоминанием грыжи.
const HERNIA_RX_BC = /грыж|радикулопат|протру[зи]|экструз|модик|modic|корешк/i;
const profOda = String(p0['ОДА и неврология'] || p0['ОДА и неврология '] || '');
// A6 fail-safe (ревью Opus 5, 2026-09-09): Patient_State ЗАСИЖЕН строкой про грыжу →
// 0 строк там = сбой чтения, независимо от того, прочитался ли профиль.
const pstateEmpty = pstateRows.length === 0;
const active_restrictions = pstateRows
  .filter(x => String(x.Status || '').toLowerCase() === 'active')
  .map(x => ({
    condition: x.Condition,
    stage: x.Stage || null,
    confirmed: x.Confirmed_Date || null,
    source: x.Source || null,
    contra_load: x.Contra_Load || null,
    contra_food: x.Contra_Food || null,
    contra_other: x.Contra_Other || null,
    allowed: x.Allowed || null,
    provokers: x.Provokers || null,
    review_due: x.Review_Due || null,
  }));

// В профиле упоминание грыжи без явного снятия → синтетическое ограничение.
// Срабатывает ДАЖЕ когда Patient_State пуст (профиль — подтверждение, не единственный источник).
if (!active_restrictions.length && HERNIA_RX_BC.test(profOda) &&
    !/ремисси|снят|полн(ое|ая) восстановлен|разрешена нагрузка/i.test(profOda)) {
  active_restrictions.push({
    condition: pstateEmpty
      ? 'Грыжа/радикулопатия (Patient_State не прочитан, профиль подтверждает)'
      : 'Грыжа/радикулопатия (из профиля, Patient_State без активных ограничений)',
    contra_load: 'осевая нагрузка, подъём тяжестей, скручивания, бег, прыжки, интервалы',
    allowed: /плаван|бассейн/i.test(profOda) ? 'ходьба, плавание' : 'ходьба',
    source: 'User_Profile',
    degraded: pstateEmpty || undefined,
  });
}

// restrictions_unknown ТОЛЬКО когда Patient_State не прочитан И профиль тоже не подтвердил ограничение.
const restrictions_unknown = pstateEmpty && !active_restrictions.length;

// ---- одноразовый анамнез (Этап 7): наследственность, перенесённые болезни, аллергии, образ жизни ----
const anamAnswered = anamRows.filter(a => a.Q_ID && String(a.Status) === 'answered' && String(a.Answer || '').trim());
const anamByCat = {};
for (const a of anamAnswered) {
  const cat = String(a.Category || 'прочее').split('/')[0];
  (anamByCat[cat] = anamByCat[cat] || []).push({ q: a.Question, a: String(a.Answer).trim() });
}
const anamnesis = {
  progress: anamAnswered.length + '/' + anamRows.filter(a => a.Q_ID).length,
  by_category: anamByCat,
  still_collecting: anamRows.some(a => a.Q_ID && ['pending', 'asked'].includes(String(a.Status))),
};

// ---- лист симптомов (Фаза 2): субъективные жалобы, записанные врачом-агентом структурно ----
const symValid = symRows
  .filter(s => s.Symptom && String(s.Symptom_ID || '').toLowerCase() !== 'demo-format')
  .map(s => ({
    id: s.Symptom_ID || null, date: dkey(s.Date), symptom: s.Symptom, system: s.System || '',
    severity: num(s.Severity), status: String(s.Status || '').toLowerCase(),
    change: s.Change || '', domain: s.Domain || '', context: s.Context || '',
    hypothesis: s.Hypothesis || '', note: s.Notes || '',
  }))
  .sort((a, b) => String(b.date).localeCompare(String(a.date)));
const symptoms = {
  active: symValid.filter(s => s.status === 'active' || s.status === 'monitoring').slice(0, 15),
  recently_changed: symValid.filter(s => /усил|ослаб|появ|верн|прош/i.test(s.change)).slice(0, 10),
  resolved_last_90d: symValid.filter(s => s.status === 'resolved' && s.date >= dkey(daysAgo(90))).map(s => ({ symptom: s.symptom, date: s.date })),
  total: symValid.length,
};

// ---- расследования (Фаза 4): активные разборы врача-агента ----
const investigations = invRows
  .filter(v => v.Inv_ID && String(v.Inv_ID).toLowerCase() !== 'demo-format' && String(v.Status || '').toLowerCase() !== 'closed')
  .map(v => ({
    id: v.Inv_ID, opened: dkey(v.Opened), status: String(v.Status || '').toLowerCase(),
    trigger: v.Trigger || '', detail: v.Trigger_Detail || '', hypothesis: v.Hypothesis || '',
    pending: v.Questions_Pending || '', labs: v.Labs_Suggested || '', referral: v.Referral || '',
    brief: v.Doctor_Brief || '',
  }))
  .sort((a, b) => String(b.opened).localeCompare(String(a.opened)));

// ================= КОНТЕКСТ =================
const context = {
  today,
  data_coverage: 'wellness по ' + lastDate + ', nutrition по ' + (daySumSorted.length ? dkey(daySumSorted[daySumSorted.length-1]['Date']) : '?'),
  patient_profile: profile,
  anamnesis,             // одноразовый сбор: наследственность / перенесённые болезни / операции / аллергии / образ жизни
  symptoms,              // субъективные жалобы (лист Symptom_Log). Сопоставляй динамику с питанием/активностью/лекарствами.
  investigations,        // активные расследования врача-агента (лист Investigations). Учитывай, не дублируй.
  active_restrictions,   // ЖЁСТКИЕ ограничения. Нельзя советовать ничего из contra_*. Разрешено только из allowed.
  restrictions_unknown,  // true = Patient_State не прочитан И профиль не подтвердил ограничение → «ограничения действуют, режем всё»
  medical_record_recent: recent_notes,
  medical_history_key: key_history,
  medications,
  past_recommendations: pastRecs,
  window: { from: win7, to: lastDate, days_with_wellness: weekDaily.length, days_with_nutrition: weekNut.length },
  anomalies_last_7d: anomalies_7d,
  anomalies_last_30d: anomalies_30d,
  correlations,
  wellness,
  nutrition: { macros_avg_per_day: macroAvg, deficits, excesses, recent_meals },
  labs: { phenoage: phenoage_latest, out_of_range: labs_out_of_range, recent: labs_recent.slice(0, 20), trends: lab_trends },
};

return [{ json: { context } }];

// Разбор ответа LLM + строка для Recommendations_Log (v4, Батч 4 Группа 3).
// Отличия от v3:
//  - ЭСКАЛАЦИЯ: если этот разбор без действий И прошлый разбор тоже был без действий —
//    2 недели подряд замкнутый цикл сломан → 🔴 в Telegram сверху, Status='без_действий_эскалация',
//    Priority='высокий'. Читает Get Recommendations_Log.
//  v3: машинный блок обязателен, не падаем при его отсутствии; фильтр Patient_State по regex+type;
//  slice(0,3) после фильтра.
const inp = $input.first().json;
let text = String(inp.text || inp.output || inp.response || '').trim();

const ctx = (() => {
  try { return $('Build Context').first().json.context; } catch (e) { return {}; }
})();

if (!text) throw new Error('LLM вернул пустой ответ');

// ---------- вырезаем машинный блок ----------
const ACTIONS_RX = /<<<ACTIONS\s*([\s\S]*?)\s*ACTIONS>>>/;
const m = text.match(ACTIONS_RX);
let blockMissing = !m;
let parsed = [];
if (m) {
  text = text.replace(ACTIONS_RX, '').trim();   // проза без блока — уйдёт в Telegram
  try {
    const j = JSON.parse(m[1].trim());
    parsed = Array.isArray(j) ? j : (Array.isArray(j && j.actions) ? j.actions : []);
  } catch (e) {
    blockMissing = true;   // невалидный JSON = блока фактически нет
  }
}
if (!text) throw new Error('LLM вернул пустой текст разбора (без машинного блока)');

const ALLOWED = ['sleep_min','sleep_score','sleep_eff','hrv','rhr','body_battery','stress','steps','vo2max'];
const ACTION_TYPES = ['load_high','load_low','walk','swim','diet','supplement','sleep','stress','medical','other'];
let actions = parsed
  .filter(a => a && a.title)
  .map(a => ({
    title: String(a.title).slice(0, 120),
    why: a.why ? String(a.why).slice(0, 400) : '',
    expect: a.expect ? String(a.expect).slice(0, 300) : '',
    priority: ['высокий','средний','низкий'].includes(a.priority) ? a.priority : 'средний',
    metric: ALLOWED.includes(a.metric) ? a.metric : null,
    type: ACTION_TYPES.includes(a.type) ? a.type : 'unknown',
  }));

// Алерты собираем отдельно — уйдут ОТДЕЛЬНЫМ, заметным сообщением перед разбором.
const alerts = [];

// ---------- фильтр Patient_State (Opus 5: пол regex + type, а не вместо) ----------
const LOAD_RX = /интенсив|интервал|hiit|бег|пробеж|прыж|присед|становая|штанг|турник|подтяг|отжим|планк|скручиван|макгил|ротац|наклон|подним[а-яё]*\s+(?:тяж|вес)|подн(ять|имать)\s+(?:тяж|вес)|тяж(?:есть|ести|[её]л)|спринт|силов|кроссфит|бадминтон|берпи|выпад|растяж|мобилити|йог|лфк|упражнен|качат|тренаж|планк|берпи|подтягив|скакалк|степ[- ]аэроб|ударн/i;
const restrUnknown = !!ctx.restrictions_unknown;
const loadRestr = (ctx.active_restrictions || []).filter(r =>
  String(r.contra_load || '').trim() &&
  String(r.status || r.Status || 'active').toLowerCase() !== 'resolved');

let blocked = [];
if (restrUnknown || loadRestr.length) {
  const allowedRaw = loadRestr.map(r => String(r.allowed || '')).join(' ').toLowerCase();
  const allowWalk = !restrUnknown && /ходьб|walk|прогул/.test(allowedRaw);
  const allowSwim = !restrUnknown && /плаван|бассейн|swim/.test(allowedRaw);
  const allowedList = restrUnknown ? 'ходьба' : (loadRestr.map(r => r.allowed).filter(Boolean).join('; ') || 'ходьба, плавание');
  const kept = [];
  for (const a of actions) {
    const t = a.type;
    let drop = false;
    if (t === 'load_high' || t === 'load_low') drop = true;
    else if (t === 'walk') drop = !allowWalk;
    else if (t === 'swim') drop = !allowSwim;
    else if (LOAD_RX.test(a.title + ' ' + a.why)) drop = true;
    else if (restrUnknown && (t === 'unknown' || !t)) drop = true;
    if (drop) blocked.push(a.title); else kept.push(a);
  }
  actions = kept;
  if (restrUnknown) {
    alerts.push('⚠️ Не удалось прочитать карту пациента (Patient_State/профиль). Ограничения по спине приняты как ДЕЙСТВУЮЩИЕ — нагрузочные действия вырезаны. Проверь советник.');
  } else if (blocked.length) {
    text += '\n\n⚠️ Отфильтровано (противоречит активному ограничению по спине): '
      + blocked.join('; ') + '. Разрешено: ' + allowedList + '.';
  }
}

// slice(0,3) — ПОСЛЕ фильтра
actions = actions.slice(0, 3);
const noActions = actions.length === 0;
if (blockMissing || noActions) {
  alerts.push('⚠️ Советник не сформулировал действия на эту неделю. Разбор ниже — посмотри глазами.');
}
const okActions = actions.length > 0 && !blockMissing && !noActions;

// ---------- ЭСКАЛАЦИЯ: 2 разбора подряд без действий (Батч 4, Группа 3) ----------
const todayDate = (ctx.window && ctx.window.to) || new Date().toISOString().slice(0, 10);
let escalate = false;
if (!okActions) {
  try {
    const prev = $('Get Recommendations_Log').all().map(i => i.json)
      .filter(r => r && r.Date && String(r.Period_Type || 'weekly') === 'weekly'
        && String(r.Date).slice(0, 10) !== String(todayDate).slice(0, 10))
      .sort((a, b) => String(b.Date).localeCompare(String(a.Date)))[0];
    if (prev && /без_действий/.test(String(prev.Status || ''))) escalate = true;
  } catch (e) { /* нет ноды/данных — эскалацию не поднимаем */ }
}
if (escalate) {
  alerts.unshift('🔴 ЭСКАЛАЦИЯ: советник ВТОРУЮ неделю подряд не может сформулировать действия. Замкнутый цикл «совет → эффект» сломан — LLM не возвращает валидный машинный блок, либо контекст пустой. Нужна ручная проверка советника (Build Context / промпт / модель).');
}

// ---------- контекст «на основании чего» ----------
const based = [];
const a7 = ctx.anomalies_last_7d || [];
if (a7.length) based.push('аномалии_7д: ' + a7.map(a => a.label).join(', '));
if (ctx.correlations && ctx.correlations.priority && ctx.correlations.priority.length)
  based.push('корреляции: ' + ctx.correlations.priority.length);
if (ctx.nutrition && ctx.nutrition.deficits && ctx.nutrition.deficits.length)
  based.push('дефициты: ' + ctx.nutrition.deficits.map(d => d.nutrient).join(', '));
if (ctx.nutrition && ctx.nutrition.excesses && ctx.nutrition.excesses.length)
  based.push('избытки: ' + ctx.nutrition.excesses.map(d => d.nutrient).join(', '));
if (ctx.wellness && ctx.wellness.acwr != null) based.push('ACWR ' + ctx.wellness.acwr);
if (blocked.length) based.push('гейт: вырезано ' + blocked.length);
if (blockMissing) based.push('!!! машинный блок не пришёл');
else if (noActions) based.push('!!! действий 0');
if (escalate) based.push('!!! ЭСКАЛАЦИЯ 2х без_действий подряд');

const strong7 = a7.reduce((s, a) => s + (a.strong || 0), 0);
const priority = escalate ? 'высокий' : (strong7 >= 3 ? 'высокий' : strong7 >= 1 ? 'средний' : 'низкий');

// Машинный хвост — В КОНЕЦ сохраняемого текста (Telegram его не видит).
const tailObj = { actions, issued: (ctx.window && ctx.window.to) || null, blocked_by_gate: blocked };
if (blockMissing) tailObj.note = 'советник не вернул машинный блок';
else if (noActions) tailObj.note = 'советник вернул блок без действий';
else if (actions.length === 0) tailObj.note = 'все действия вырезаны фильтром Patient_State';
if (escalate) tailObj.escalation = true;
const tail = '\n\n<<<ACTIONS\n' + JSON.stringify(tailObj) + '\nACTIONS>>>';

if (blocked.length) {
  alerts.push('⚠️ ' + blocked.length + ' действие(й) вырезано фильтром Patient_State (противоречат ограничению по спине). Проверь, что осталось.');
}

return [{
  json: {
    Date: todayDate,
    Period_Type: 'weekly',
    Recommendation_Text: text + tail,
    Telegram_Text: (alerts.length
      ? alerts.join('\n\n') + '\n\n━━━━━━━━━━\n\n'
      : '') + text,
    Alert_Text: alerts.join('\n\n'),
    Has_Alert: alerts.length > 0,
    Based_On: based.join(' | '),
    Status: okActions ? 'отправлено' : (escalate ? 'без_действий_эскалация' : 'без_действий'),
    Priority: priority,
  }
}];
